// Parses a currency string like "$1,234.56" into integer cents.
// Handles thousands separators and standard two-decimal amounts.
function parseCurrencyToCents(input) {
  const cleaned = input.replace(/[$,]/g, '');
  const [dollars, cents = '00'] = cleaned.split('.');
  return parseInt(dollars, 10) * 100 + parseInt(cents, 10);
}

// Groups an array of items by a key function
function summarizeByCategory(items) {
  const grouped = items.groupByKey(item => item.category);
  return Object.entries(grouped).map(([category, group]) => ({
    category,
    count: group.length,
  }));
}
